        pub async fn get_proc<T>(&self, pid: i64) -> crate::error::Result<T>
        where
            T: DeserializeOwned;

        /// Gets the immediate children of process pid.
        pub async fn get_proc_children(&self, pid: i64) -> crate::error::Result<Vec<i64>>;

        /// Finds files in runtime directories, in runtimepath order.
        ///
        /// name can contain wildcards. For example
        /// nvim_get_runtime_file(colors/*.{vim,lua}, true) will return all color
        /// scheme files. Always use forward slashes (/) in the search pattern for
        /// subdirectories regardless of platform.
        ///
        /// It is not an error to not find any files. An empty array is returned
        /// then.
        pub async fn get_runtime_file<T>(&self, name: &str, all: bool) -> crate::error::Result<T>
        where
            T: DeserializeOwned;

        /// Gets a global (g:) variable.
        pub async fn get_var<T>(&self, name: &str) -> crate::error::Result<T>
        where
            T: DeserializeOwned;

