        pub async fn open_tabpage(
            &self,
            buf: &Buffer,
            enter: bool,
            config: HashMap<String, Value>,
        ) -> crate::error::Result<TabPage>;

        /// Open a terminal instance in a buffer
        ///
        /// By default (and currently the only option) the terminal will not be
        /// connected to an external process. Instead, input sent on the channel
        /// will be echoed directly by the terminal. This is useful to display
        /// ANSI terminal sequences returned as part of a rpc message, or
        /// similar.
        ///
        /// Note: to directly initiate the terminal using the right size, display
        /// the buffer in a configured window before calling this. For instance,
        /// for a floating display, first create an empty buffer using
        /// |nvim_create_buf()|, then display it using |nvim_open_win()|, and
        /// then call this function. Then |nvim_chan_send()| can be called
        /// immediately to process sequences in a virtual terminal having the
        /// intended size.
        pub async fn open_term(
            &self,
            buf: &Buffer,
            opts: HashMap<String, Value>,
        ) -> crate::error::Result<i64>;

        /// Opens a new split window, or a floating window if relative is specified,
        /// or an external window (managed by the UI) if external is specified.
        ///
        /// Floats are windows that are drawn above the split layout, at some anchor
        /// position in some other window. Floats can be drawn internally or by
        /// external GUI with the |ui-multigrid| extension. External windows are
        /// only supported with multigrid GUIs, and are displayed as separate
        /// top-level windows.
        ///
        /// For a general overview of floats, see |api-floatwin|.
        ///
        /// The width and height of the new window must be specified when opening
        /// a floating window, but are optional for normal windows.
        ///
        /// If relative and external are omitted, a normal split window is
        /// created. The win property determines which window will be split. If no
        /// win is provided or win == 0, a window will be created adjacent to the
        /// current window. If -1 is provided, a top-level split will be created.
        /// vertical and split are only valid for normal windows, and are used to
        /// control split direction. For vertical, the exact direction is determined
        /// by splitright and splitbelow. Split windows cannot have
        /// bufpos/row/col/border/title/footer properties.
        ///
        /// With relative=editor (row=0,col=0) refers to the top-left corner of the
        /// screen-grid and (row=Lines-1,col=Columns-1) refers to the bottom-right
        /// corner. Fractional values are allowed, but the builtin implementation
        /// (used by non-multigrid UIs) will always round down to nearest integer.
        ///
        /// Out-of-bounds values, and configurations that make the float not fit
        /// inside the main editor, are allowed. The builtin implementation
        /// truncates values so floats are fully within the main screen grid.
        /// External GUIs could let floats hover outside of the main window like
        /// a tooltip, but this should not be used to specify arbitrary WM
        /// screen positions.
        pub async fn open_win(
            &self,
            buf: &Buffer,
            enter: bool,
            config: WindowConf,
        ) -> crate::error::Result<Window>;

        /// Parse command line.
        ///
        /// Does not check the validity of command arguments.
        pub async fn parse_cmd(
            &self,
            str: &str,
            opts: HashMap<String, Value>,
        ) -> crate::error::Result<HashMap<String, Value>>;

        /// Parse a Vimscript expression.
        pub async fn parse_expression(
            &self,
            expr: &str,
            flags: &str,
            hl: bool,
        ) -> crate::error::Result<HashMap<String, Value>>;

        /// Pastes at cursor (in any mode), and sets redo so dot (|.|) will repeat
        /// the input. UIs call this to implement paste, but it is also intended for
        /// use by scripts to input large, dot-repeatable blocks of text (as opposed
        /// to |nvim_input()| which is subject to mappings/events and is thus much
        /// slower).
        ///
        /// Invokes the |vim.paste()| handler, which handles each mode
        /// appropriately.
        ///
        /// Errors (nomodifiable, vim.paste() failure, …) are reflected in err
        /// but do not affect the return value (which is strictly decided by
        /// vim.paste()). On error or cancel, subsequent calls are ignored
        /// (drained) until the next paste is initiated (phase 1 or -1).
        pub async fn paste(&self, data: &str, crlf: bool, phase: i64)
        -> crate::error::Result<bool>;

        /// Puts text at cursor, in any mode. For dot-repeatable input, use
        /// |nvim_paste()|.
        ///
        /// Compare |:put| and |p| which are always linewise.
        pub async fn put(
            &self,
            lines: Vec<String>,
            typ: &str,
            after: bool,
            follow: bool,
        ) -> crate::error::Result<()>;

