        pub async fn raw_notify(
            &self,
            method: &str,
            params: &[Value],
        ) -> crate::error::Result<(), RpcError>;

        /// Make a raw request over the MessagePack-RPC protocol.
        pub async fn raw_request(
            &self,
            method: &str,
            params: &[Value],
        ) -> crate::error::Result<Value, RpcError>;

