pub mod test {
    //! Utilities for writing tests for Nvi plugins.

    /// A handle to a running test instance.
    pub struct NviTest {
        /// The client connected to the test instance.
        pub client: Client,
        /* private fields */
    }

    impl NviTest {
        /// Assert that a log message containing the given string exists
        pub fn assert_log(&self, contains: &str);

        /// Wait for a log message containing the given string to appear, with a
        /// default timeout of 5 seconds
        pub async fn await_log(&self, contains: &str) -> crate::error::Result<()>;

        /// Wait for a log message containing the given string to appear, with a
        /// timeout
        pub async fn await_log_timeout(
            &self,
            contains: &str,
            timeout: Duration,
        ) -> crate::error::Result<()>;

        /// Create a new NviTest builder - the recommended way to create a test
        /// instance
        pub fn builder() -> NviTestBuilder;

        /// Execute two closures concurrently, returning the result of the first
        /// when it completes and abandoning the second.
        pub async fn concurrent<T, A, B>(&self, a: A, b: B) -> crate::error::Result<T>
        where
            A: 'static + FnOnce(Client) -> BoxFuture<'static, crate::error::Result<T>> + Send,
            B: 'static + FnOnce(Client) -> BoxFuture<'static, crate::error::Result<()>> + Send,
            T: 'static + Send;

        /// Send termination signal and await all tasks.
        pub async fn finish(self) -> crate::error::Result<()>;

        /// Get a copy of the current logs
        pub fn logs(&self) -> Vec<String>;
    }

    /// Builder for NviTest configuration
    #[derive(Default)]
    pub struct NviTestBuilder<T = ()> {/* private fields */}

    impl NviTestBuilder<()> {
        /// Run the test with no plugin
        pub async fn run(self) -> crate::error::Result<NviTest>;
    }

    impl<T> NviTestBuilder<T>
    where
        T: 'static + NviPlugin + Sync + Unpin,
    {
        /// Run the test with the configured plugin
        pub async fn run(self) -> crate::error::Result<NviTest>;
    }

    impl<T> NviTestBuilder<T> {
        /// Set the log level for the test
        pub fn log_level(self, level: Level) -> Self;

        /// Enable or disable log output to stdout
        pub fn show_logs(self) -> Self;

        /// Add a plugin to the test instance
        pub fn with_plugin<P>(self, plugin: P) -> NviTestBuilder<P>
        where
            P: 'static + NviPlugin + Sync + Unpin;
    }

    /// Run a test service, starting a neovim headless instance and connecting to
    /// it. When a signal is received on the broadcast channel, all tasks are
    /// stopped. This variant takes the shutdown signal as an argument, for cases
    /// where the caller wants to pass the signal into the plugin itself. This is
    /// mostly useful for Nvi's internal tests.
    pub async fn run_plugin_with_shutdown<T>(
        nvi: T,
        shutdown_tx: Sender<()>,
    ) -> crate::error::Result<()>
    where
        T: 'static + NviPlugin + Sync + Unpin;

    /// Wait a short while for a path to exist.
    ///
    /// Returns an error after 500ms if the path has not appeared.
    pub async fn wait_for_path(path: &Path) -> crate::error::Result<()>;
}

pub mod ui {
    //! Higher-level user interface components.

    pub mod pane {
        //! A window pane, which is a window and a buffer managed in concert. This is
        //! the base for non-editing interface windows.

        /// A window pane, which is a window and a buffer managed in concert. This
        /// struct is intended for interface windows, especially floats - that is,
        /// windows that aren't used for editing text directly.
        #[derive(Clone, Debug)]
        pub struct Pane {
            /// The window handle.
            pub window: Window,
            /// The buffer handle.
            pub buffer: Buffer,
            /// The content of the pane.
            pub content: crate::ui::pane::Text,
        }

        impl Pane {
            /// Creates a new pane builder.
            pub fn builder() -> PaneBuilder;

            /// Destroys the window and buffer, consuming the pane.
            pub async fn destroy(self, client: &mut Client) -> crate::error::Result<()>;
        }

        /// Builder for constructing a Pane.
        ///
        /// By default, panes are not focusable. This means that the cursor cannot enter
        /// the window using normal window movement commands. This is useful for UI
        /// elements that should not interfere with normal window navigation.
        #[derive(Default)]
        pub struct PaneBuilder {/* private fields */}

        impl PaneBuilder {
            /// Builds the pane with the configured options, creating the underlying
            /// buffer and window.
            pub async fn build(
                self,
                client: &mut Client,
                content: crate::ui::pane::Text,
            ) -> crate::error::Result<Pane>;

            /// Sets whether the window receives focus when created.
            /// Default is false.
            pub fn enter(self, value: bool) -> Self;

            /// Sets whether the pane can be focused through normal window navigation.
            /// Default is false.
            pub fn focusable(self, value: bool) -> Self;

            /// Adds a highlight group mapping for the window. All mappings are applied
            /// to the window through the `winhl` option.
            pub fn winhl(self, from: &str, to: &str) -> Self;

            /// Sets the border style for the pane.
            pub fn with_border(self, border: Border) -> Self;

            /// Positions the pane relative to the editor window.
            pub fn with_editor_pos(self, pos: Pos, padding: u64) -> Self;

            /// Positions the pane relative to another window.
            pub fn with_win_pos(self, win: Window, pos: Pos, padding: u64) -> Self;

            /// Sets a base window configuration. Other builder methods will override
            /// these settings.
            pub fn with_window_conf(self, conf: WindowConf) -> Self;
        }

        /// A quick way to position a window relative to another window or the editor.
        #[derive(Debug)]
        pub enum Pos {
            /// Top left corner
            NE,
            /// Top center
            N,
            /// Top right corner
            NW,
            /// Middle left
            E,
            /// Middle right
            W,
            /// Bottom left corner
            SE,
            /// Bottom center
            S,
            /// Bottom right corner
            SW,
            /// Centered
            Center,
        }

        impl Pos {
            /// Calculate window position given dimensions and padding
            ///
            /// # Arguments
            ///
            /// * `enclosing` - (width, height) of the enclosing window
            /// * `target` - (width, height) of the target window to position
            /// * `padding` - padding from the anchor point
            ///
            /// Returns (row, col) coordinates assuming NE anchor
            pub fn win_pos(
                &self,
                enclosing: (u64, u64),
                target: (u64, u64),
                padding: u64,
            ) -> (f64, f64);
        }

        /// Textual content to be displayed in a window pane.
        #[derive(Clone, Debug)]
        pub struct Text {/* private fields */}

        impl crate::ui::pane::Text {
            /// Creates a blank content area of specified width and height, filled with
            /// spaces.
            pub fn blank(width: usize, height: usize) -> Self;

            /// Creates a content area of specified width and height with text centered
            /// in both dimensions.
            pub fn center(width: usize, height: usize, text: &str) -> Self;

            /// Creates new content from a vector of strings.
            pub fn new(lines: Vec<String>) -> Self;

            /// Returns the dimensions of the content as (width, height).
            /// Width is the length of the longest line, height is the number of lines.
            pub fn size(&self) -> (usize, usize);
        }
    }
}
